def spacedHarvest(nums, d):
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    vals = sorted(cnt)
    dp = [0] * (len(vals) + 1)
    j = 0
    for i, v in enumerate(vals):
        while vals[j] <= v - d:
            j += 1
        dp[i + 1] = max(dp[i], v * cnt[v] + dp[j])
    return dp[len(vals)]
